import numpy as np
from scipy.optimize import least_squares
t=df['t'];P=df['P'];y=df['dP_dt']
gs={
 'tk':lambda p: t**p[0],
 'log1pt':lambda p: np.log(1+p[0]*t),
 '1-exp':lambda p: 1-np.exp(-p[0]*t),
 'tanh':lambda p: np.tanh(p[0]*t),
 'sat':lambda p: t/(1+p[0]*t),
 'texpk':lambda p: t*np.exp(-p[0]*t),
}
res={}
for name,g in gs.items():
    best=None
    rng=np.random.default_rng(1)
    for i in range(25):
        p0=[rng.normal(0.6,0.3),rng.normal(3,1),rng.uniform(0.2,0.6),rng.normal(0,0.5),rng.normal(1,0.5),rng.uniform(0.2,2),rng.normal(0,1)]
        def model(p):
            a,b,w,d,e,q,phi=p
            return a*t + b*np.sin(w*t+phi)/P + d*P*np.log(P) + e*g([q])/P
        try:
            r=least_squares(lambda p: model(p)-y,p0,max_nfev=2000)
            if best is None or r.cost<best.cost: best=r
        except Exception: pass
    res[name]=(np.mean((best.fun)**2)/np.var(y), np.round(best.x,4))
